// Looks up a single standalone emoji glyph (e.g. a notice's `icon` field) by exact match.
export function emojiFile(ch: string): string | undefined {
  return EMOJI_FILES[ch]
}

// Splits a leading emoji (with its trailing space) off a guide/tip line, for swapping it with the
// flat OpenMoji icon. Tries the longest glyphs first (some are 2 UTF-16 code units plus a VS16 selector).
export function splitLeadingEmoji(text: string): { icon?: string; rest: string } {
  for (const len of [3, 2, 1]) {
    const file = EMOJI_FILES[text.slice(0, len)]
    if (file) return { icon: file, rest: text.slice(len).replace(/^\s+/, "") }
  }
  return { rest: text }
}
